functions.init_scanner:
static void init_scanner(Scanner *s, const char *src, int src_len)
{
    s->src = src;
    s->len = src_len;
    s->cur = 0;
}

functions.set_cur:
static void set_cur(Scanner *s, int n)
{
    s->cur = n;
}

functions.peek_next:
static char peek_next(Scanner *s)
{
    if (s->cur >= s->len - 1)
        return '\0';
    return s->src[s->cur + 1];
}

functions.advance2:
static char advance2(Scanner *s, int n)
{
    for (int i = 0; i < n - 1; i++)
        s->cur++;
    return s->src[s->cur++];
}

functions.skip_whitespace:
static void skip_whitespace(Scanner *s)
{
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISspace))
        advance(s);
}

functions.skip_blank:
static void skip_blank(Scanner *s)
{
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISspace) && peek(s) != '\n')
        advance(s);
}

functions.skip_comment:
static void skip_comment(Scanner *s)
{
    while (!is_at_end(s) && peek(s) == '#')
    {
        do
            advance(s);
        while (!is_at_end(s) && peek(s) != '\n');
    }
}

functions.skip_whitespace_and_comments:
void skip_whitespace_and_comments(Scanner *s)
{
    while (!is_at_end(s) && (((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISspace) || peek(s) == '#'))
    {
        skip_whitespace(s);
        skip_comment(s);
    }
}

