functions.match_literal:
static _Bool match_literal(Scanner *s, int offset, const char *literal, int len)
{
    if (offset + len > s->len)
        return 0;
    return !strncmp(s->src + offset, literal, len);
}

functions.consume_literal:
static _Bool consume_literal(Scanner *s, int offset, const char *literal, int len)
{
    if (match_literal(s, offset, literal, len))
    {
        advance2(s, len);
        return 1;
    }
    return 0;
}

functions.is_key:
static _Bool is_key(char ch)
{
    return ((*__ctype_b_loc())[(int)((ch))] & (unsigned short int)_ISalpha) || ch == '.' || ch == '_';
}

functions.is_string:
static _Bool is_string(char ch)
{
    return ((*__ctype_b_loc())[(int)((ch))] & (unsigned short int)_ISalnum) ||
           ((*__ctype_b_loc())[(int)((ch))] & (unsigned short int)_ISblank) ||
           (((*__ctype_b_loc())[(int)((ch))] & (unsigned short int)_ISpunct) && ch != '"');
}

