functions.error:
static int error(Scanner *s, CfgError *err, const char *fmt, ...)
{
    const char prefix[] = "";
    const int prefix_len = sizeof(prefix) - 1;
    err->off = cur(s);
    err->row = 1;
    err->col = 1;
    for (int i = 0; i < cur(s); i++)
    {
        err->col++;
        if (s->src[i] == '\n')
        {
            err->row++;
            err->col = 1;
        }
    }
    va_list vargs;
    __builtin_va_start(vargs, fmt);
    snprintf(err->msg, 64, prefix);
    vsnprintf(err->msg + prefix_len, 64 - prefix_len, fmt, vargs);
    __builtin_va_end(vargs);
    return -1;
}

functions.cfg_fprint_error:
void cfg_fprint_error(FILE *stream, CfgError *err)
{
    if (err->row == -1 && err->col == -1)
        fprintf(stream, "Error: %s\n", err->msg);
    else
        fprintf(stream, "Error at %d:%d :: %s\n", err->row, err->col, err->msg);
}

functions.parse_string:
static int parse_string(Scanner *s, CfgEntry *entry, CfgError *err)
{
    advance(s);
    int val_offset = cur(s);
    while (!is_at_end(s) && is_string(peek(s)))
        advance(s);
    if (is_at_end(s) || peek(s) != '"')
        return error(s, err, "closing '\"' expected");
    int val_len = cur(s) - val_offset;
    if (val_len > 64)
        return error(s, err, "value too long");
    advance(s);
    copy_slice_into(s, val_offset, val_len, entry->val.string, sizeof(entry->val.string));
    entry->type = CFG_TYPE_STRING;
    return 0;
}

functions.consume_int:
static int consume_int(Scanner *s, int *number, CfgError *err)
{
    int sign = 1;
    int num = 0;
    if (!is_at_end(s) && peek(s) == '-' && ((*__ctype_b_loc())[(int)((peek_next(s)))] & (unsigned short int)_ISdigit))
    {
        advance(s);
        sign = -1;
    }
    if (!is_at_end(s) && !((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
        return error(s, err, "number expected");
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
    {
        int digit = advance(s) - '0';
        if (num > (0x7fffffff - digit) / 10)
            return error(s, err, "number too large");
        num = num * 10 + digit;
    }
    *number = sign * num;
    return 0;
}

functions.consume_float:
static int consume_float(Scanner *s, float *number, CfgError *err)
{
    int sign = 1;
    int int_part = 0;
    int fract_part = 0;
    if (!is_at_end(s) && peek(s) == '-' && ((*__ctype_b_loc())[(int)((peek_next(s)))] & (unsigned short int)_ISdigit))
    {
        advance(s);
        sign = -1;
    }
    if (!is_at_end(s) && !((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
        return error(s, err, "number expected");
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
    {
        int digit = advance(s) - '0';
        if (int_part > (0x7fffffff - digit) / 10)
            return error(s, err, "number too large");
        int_part = int_part * 10 + digit;
    }
    if (!is_at_end(s) && peek(s) != '.')
        return error(s, err, "float expected");
    advance(s);
    int div = 1;
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
    {
        int digit = advance(s) - '0';
        if (fract_part > (0x7fffffff - digit) / 10)
            return error(s, err, "number too large");
        fract_part = fract_part * 10 + digit;
        if (div > 0x7fffffff / 10)
            return error(s, err, "number too large");
        div *= 10;
    }
    float floating = int_part + ((float)fract_part / div);
    *number = sign * floating;
    return 0;
}

functions.match_float:
static _Bool match_float(Scanner *s)
{
    int restore = cur(s);
    _Bool is_float = 0;
    if (!is_at_end(s) && peek(s) == '-' && ((*__ctype_b_loc())[(int)((peek_next(s)))] & (unsigned short int)_ISdigit))
        advance(s);
    while (!is_at_end(s) && ((*__ctype_b_loc())[(int)((peek(s)))] & (unsigned short int)_ISdigit))
        advance(s);
    if (!is_at_end(s) && peek(s) == '.')
        is_float = 1;
    set_cur(s, restore);
    return is_float;
}

functions.parse_number:
static int parse_number(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (match_float(s))
    {
        float number;
        if (consume_float(s, &number, err) != 0)
            return -1;
        entry->val.floating = number;
        entry->type = CFG_TYPE_FLOAT;
    }
    else
    {
        int number;
        if (consume_int(s, &number, err) != 0)
            return -1;
        entry->val.integer = number;
        entry->type = CFG_TYPE_INT;
    }
    return 0;
}

functions.parse_rgba:
static int parse_rgba(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (!consume_literal(s, cur(s), "rgba", 4))
        return error(s, err, "invalid literal");
    skip_blank(s);
    if (is_at_end(s) || peek(s) != '(')
        return error(s, err, "'(' expected");
    advance(s);
    uint8_t rgb[3];
    for (int i = 0; i < 3; i++)
    {
        skip_blank(s);
        if (match_float(s))
            return error(s, err,
                         "red, blue and green must be "
                         "integers in range [0, 255]");
        int number;
        if (consume_int(s, &number, err) != 0)
            return -1;
        if (number < 0 || number > 255)
            return error(s, err,
                         "red, blue and green must be "
                         "integers in range [0, 255]");
        rgb[i] = (uint8_t)number;
        skip_blank(s);
        if (is_at_end(s) || peek(s) != ',')
            return error(s, err, "',' expected");
        advance(s);
    }
    skip_blank(s);
    uint8_t alpha;
    if (match_float(s))
    {
        float number;
        if (consume_float(s, &number, err) != 0)
            return -1;
        if (number < 0 || number > 1)
            return error(s, err, "alpha must be in range [0, 1]");
        alpha = number * 255;
    }
    else
    {
        int number;
        if (consume_int(s, &number, err) != 0)
            return -1;
        if (number < 0 || number > 1)
            return error(s, err, "alpha must be in range [0, 1]");
        alpha = number * 255;
    }
    skip_blank(s);
    if (is_at_end(s) || peek(s) != ')')
        return error(s, err, "')' expected");
    advance(s);
    entry->val.color = (CfgColor){
        .r = rgb[0],
        .g = rgb[1],
        .b = rgb[2],
        .a = alpha,
    };
    entry->type = CFG_TYPE_COLOR;
    return 0;
}

functions.parse_true:
static int parse_true(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (!consume_literal(s, cur(s), "true", 4))
        return error(s, err, "invalid literal");
    entry->val.boolean = 1;
    entry->type = CFG_TYPE_BOOL;
    return 0;
}

functions.parse_false:
static int parse_false(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (!consume_literal(s, cur(s), "false", 5))
        return error(s, err, "invalid literal");
    entry->val.boolean = 0;
    entry->type = CFG_TYPE_BOOL;
    return 0;
}

functions.parse_literal:
static int parse_literal(Scanner *s, CfgEntry *entry, CfgError *err)
{
    switch (peek(s))
    {
    case 't':
        return parse_true(s, entry, err);
    case 'f':
        return parse_false(s, entry, err);
    case 'r':
        return parse_rgba(s, entry, err);
    default:
        return error(s, err, "invalid literal");
    }
}

functions.parse_value:
static int parse_value(Scanner *s, CfgEntry *entry, CfgError *err)
{
    skip_blank(s);
    if (is_at_end(s) || peek(s) == '\n')
        return error(s, err, "missing value");
    char c = peek(s);
    if (c == '"')
        return parse_string(s, entry, err);
    else if (((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISalpha))
        return parse_literal(s, entry, err);
    else if (((*__ctype_b_loc())[(int)((c))] & (unsigned short int)_ISdigit) ||
             (c == '-' && ((*__ctype_b_loc())[(int)((peek_next(s)))] & (unsigned short int)_ISdigit)))
        return parse_number(s, entry, err);
    else
        return error(s, err, "invalid value");
}

functions.parse_key:
static int parse_key(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (is_at_end(s) || !is_key(peek(s)))
        return error(s, err, "missing key");
    int key_offset = cur(s);
    do
        advance(s);
    while (!is_at_end(s) && is_key(peek(s)));
    int key_len = cur(s) - key_offset;
    if (key_len > 32)
        return error(s, err, "key too long");
    copy_slice_into(s, key_offset, key_len, entry->key, sizeof(entry->key));
    return 0;
}

functions.consume_colon:
static int consume_colon(Scanner *s, CfgError *err)
{
    skip_blank(s);
    if (is_at_end(s) || peek(s) != ':')
        return error(s, err, "':' expected");
    advance(s);
    return 0;
}

functions.parse_entry:
static int parse_entry(Scanner *s, CfgEntry *entry, CfgError *err)
{
    if (parse_key(s, entry, err) != 0)
        return -1;
    if (consume_colon(s, err) != 0)
        return -1;
    if (parse_value(s, entry, err) != 0)
        return -1;
    skip_blank(s);
    if (!is_at_end(s) && peek(s) == '#')
        skip_comment(s);
    if (!is_at_end(s) && peek(s) != '\n')
        return error(s, err, "unexpected character '%c'", peek(s));
    if (!is_at_end(s))
        advance(s);
    return 0;
}

functions.cfg_parse:
int cfg_parse(const char *src, int src_len, Cfg *cfg, CfgError *err)
{
    Scanner s;
    init_scanner(&s, src, src_len);
    init_error(err);
    cfg->count = 0;
    skip_whitespace_and_comments(&s);
    while (!is_at_end(&s) && cfg->count < cfg->capacity)
    {
        CfgEntry *entry = &cfg->entries[cfg->count];
        if (parse_entry(&s, entry, err) != 0)
            return -1;
        cfg->count++;
        skip_whitespace_and_comments(&s);
    }
    return 0;
}

functions.read_file:
static char *read_file(const char *filename, int *count, char *err)
{
    FILE *file = fopen(filename, "rb");
    if (!file)
    {
        snprintf(err, 64, "failed to open file");
        return ((void *)0);
    }
    fseek(file, 0, 2);
    size_t file_size = (size_t)ftell(file);
    rewind(file);
    char *src = malloc(file_size + 1);
    if (src == ((void *)0))
    {
        snprintf(err, 64, "memory allocation failed");
        return ((void *)0);
    }
    size_t bytes_read = fread(src, sizeof(char), file_size, file);
    fclose(file);
    if (bytes_read != file_size)
    {
        free(src);
        snprintf(err, 64, "failed to read file");
        return ((void *)0);
    }
    *count = file_size;
    return src;
}

functions.cfg_parse_file:
int cfg_parse_file(const char *filename, Cfg *cfg, CfgError *err)
{
    init_error(err);
    size_t len = strlen(filename);
    if (len < 5)
    {
        snprintf(err->msg, 64, "invalid filename");
        return -1;
    }
    const char *ext = filename + (len - (sizeof(".cfg") - 1));
    if (strcmp(ext, ".cfg") != 0)
    {
        snprintf(err->msg, 64, "invalid file extension");
        return -1;
    }
    int src_len;
    char *src = read_file(filename, &src_len, err->msg);
    if (src == ((void *)0))
        return -1;
    int res = cfg_parse(src, src_len, cfg, err);
    free(src);
    return res;
}

