static void *get_val(Cfg *cfg, const char *key, void *fallback, CfgValType type)
{
    for (int i = cfg->count - 1; i >= 0; i--)
    {
        if (cfg->entries[i].type == type && !strcmp(key, cfg->entries[i].key))
            return &(cfg->entries[i].val);
    }
    return fallback;
}

